/**
 * Compresse une image côté navigateur avant tout envoi réseau.
 * Critique pour les étudiants sur connexions 3G/2G africaines :
 * une photo de caméra Android passe de ~6 Mo → ~350 Ko (×17 plus rapide).
 *
 * @param {File|Blob} file
 * @param {object} opts
 * @param {number} opts.maxWidth  - px max (défaut 1920)
 * @param {number} opts.maxHeight - px max (défaut 1920)
 * @param {number} opts.quality   - JPEG 0–1 (défaut 0.80)
 * @param {number} opts.maxKB     - taille cible en Ko (défaut 700). Si déjà en dessous, pas de compression.
 * @returns {Promise<Blob>}       - Blob compressé (ou original si non-image / déjà petite)
 */
export async function compressImage(file, {
  maxWidth  = 1920,
  maxHeight = 1920,
  quality   = 0.80,
  maxKB     = 700,
} = {}) {
  if (!file) return file;

  const type = file.type || '';
  if (!type.startsWith('image/')) return file;           // Non-image : pas de compression
  if (file.size <= maxKB * 1024) return file;            // Déjà assez petite

  return new Promise((resolve) => {
    const img  = new Image();
    const blobUrl = URL.createObjectURL(file instanceof Blob ? file : new Blob([file], { type }));

    img.onload = () => {
      URL.revokeObjectURL(blobUrl);

      let { width, height } = img;
      const ratio = Math.min(maxWidth / width, maxHeight / height, 1);
      width  = Math.round(width  * ratio);
      height = Math.round(height * ratio);

      const canvas = document.createElement('canvas');
      canvas.width  = width;
      canvas.height = height;
      canvas.getContext('2d').drawImage(img, 0, 0, width, height);

      // Toujours JPEG pour les photos — PNG serait trop lourd
      const outputType = type === 'image/png' ? 'image/png' : 'image/jpeg';
      const outputQuality = outputType === 'image/png' ? undefined : quality;

      canvas.toBlob(
        (blob) => resolve(blob || file),
        outputType,
        outputQuality,
      );
    };

    img.onerror = () => { URL.revokeObjectURL(blobUrl); resolve(file); };
    img.src = blobUrl;
  });
}
