import React, { useState, useRef, useCallback, useEffect } from 'react';
import {
  Upload, X, Send, Loader, Sparkles,
  BookOpen, Brain, Search, PenLine, Key, RotateCcw, FileText, Download, Camera,
} from 'lucide-react';
