// Capacitor WebView sert l'app sur 'localhost' même en production mobile
// → ne pas traiter comme dev local
const IS_NATIVE_APP = !!(
  (typeof window !== 'undefined') && (window.Capacitor?.isNativePlatform?.() || window.Capacitor?.platform)
);
const isRunningLocally = () =>
  !IS_NATIVE_APP &&
  (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1');

// ─── Types de fichiers acceptés ───────────────────────────────────────────────
const ACCEPT = '.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.png,.jpg,.jpeg,.webp,.gif';

// Correspondance extension → MIME (Android retourne souvent type vide pour PDF/Word)
const EXT_MIME = {
  pdf:  'application/pdf',
  doc:  'application/msword',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  ppt:  'application/vnd.ms-powerpoint',
  pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  xls:  'application/vnd.ms-excel',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  txt:  'text/plain', csv: 'text/csv',
  png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg',
  gif: 'image/gif', webp: 'image/webp',
};

/** Lit immédiatement un File Android (content:// URI) en ArrayBuffer stable. */
async function stabiliserFichier(f) {
  if (!f) return null;
  const ext = (f.name || '').split('.').pop().toLowerCase();
  const mime = f.type || EXT_MIME[ext] || 'application/octet-stream';
  try {
    const buf = await f.arrayBuffer();
    return new File([buf], f.name || 'document', { type: mime });
  } catch {
    return f; // fallback : on garde le fichier original
  }
}

const FILE_ICON = (name = '') => {
  const ext = (name.split('.').pop() || '').toLowerCase();
  if (ext === 'pdf') return '📄';
  if (['doc', 'docx'].includes(ext)) return '📝';
  if (['ppt', 'pptx'].includes(ext)) return '📊';
  if (['xls', 'xlsx'].includes(ext)) return '📈';
  if (['png', 'jpg', 'jpeg', 'webp', 'gif'].includes(ext)) return '🖼️';
  return '📎';
};

// ─── Rendu Markdown — bleu ciel + orange ──────────────────────────────────
function inlineMd(text) {
  if (!text) return '';
  return text
    .split(/(\*\*[^*\n]+\*\*|\*[^*\n]+\*|`[^`\n]+`)/)
    .map((part, i) => {
      if (part.startsWith('**') && part.endsWith('**'))
        // Gras → bleu ciel lumineux
        return <strong key={i} style={{ color: '#7dd3fc', fontWeight: 700 }}>{part.slice(2, -2)}</strong>;
      if (part.startsWith('*') && part.endsWith('*'))
        // Italique → orange
        return <em key={i} style={{ color: '#fb923c', fontStyle: 'italic' }}>{part.slice(1, -1)}</em>;
      if (part.startsWith('`') && part.endsWith('`'))
        return <code key={i} style={{
          background: 'rgba(14,165,233,0.12)', padding: '1px 6px', borderRadius: 4,
          fontSize: '0.81em', color: '#67e8f9', fontFamily: 'monospace',
          border: '1px solid rgba(14,165,233,0.2)',
        }}>{part.slice(1, -1)}</code>;
      return part;
    });
}

function MarkdownMsg({ text }) {
  if (!text) return null;
  const lines = text.split('\n');
  const out = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];

    // Code block
    if (line.trimStart().startsWith('```')) {
      const codeLines = [];
      i++;
      while (i < lines.length && !lines[i].trimStart().startsWith('```')) {
        codeLines.push(lines[i]);
        i++;
      }
      i++; // skip closing ```
      out.push(
        <pre key={`cb${i}`} style={{
          background: 'rgba(2,8,20,0.7)',
          border: '1px solid rgba(14,165,233,0.2)',
          borderLeft: '4px solid #0284c7',
          borderRadius: '0 8px 8px 0',
          padding: '10px 14px', overflowX: 'auto',
          fontSize: '0.79rem', color: '#7dd3fc', margin: '8px 0', lineHeight: 1.6,
          whiteSpace: 'pre-wrap', wordBreak: 'break-word',
          fontFamily: '"Fira Code","Consolas","Courier New",monospace',
        }}>
          {codeLines.join('\n')}
        </pre>
      );
      continue;
    }

    // Heading # / ## / ###
    const hm = line.match(/^(#{1,3})\s+(.+)$/);
    if (hm) {
      const lvl = hm[1].length;
      // H1 : bleu avec bordure basse, H2 : bordure gauche orange, H3 : discret
      out.push(
        <div key={`h${i}`} style={{
          fontWeight: 800,
          color: lvl === 1 ? '#38bdf8' : lvl === 2 ? '#7dd3fc' : '#93c5fd',
          fontSize: lvl === 1 ? '1.05rem' : lvl === 2 ? '0.96rem' : '0.9rem',
          marginTop: lvl === 1 ? '20px' : lvl === 2 ? '14px' : '10px',
          marginBottom: lvl === 1 ? '8px' : '5px',
          paddingBottom: lvl === 1 ? '6px' : '0',
          borderBottom: lvl === 1 ? '1.5px solid rgba(56,189,248,0.2)' : 'none',
          paddingLeft: lvl === 2 ? '10px' : '0',
          borderLeft: lvl === 2 ? '3px solid #f97316' : 'none',
          lineHeight: 1.3,
        }}>
          {inlineMd(hm[2])}
        </div>
      );
      i++; continue;
    }

    // Bullet list block — flèche bleue
    if (line.match(/^[\-*•]\s+/)) {
      const items = [];
      while (i < lines.length && lines[i].match(/^[\-*•]\s+/)) {
        items.push(lines[i].replace(/^[\-*•]\s+/, ''));
        i++;
      }
      out.push(
        <ul key={`ul${i}`} style={{ margin: '6px 0 8px', paddingLeft: 0, listStyle: 'none' }}>
          {items.map((it, j) => (
            <li key={j} style={{
              display: 'flex', alignItems: 'flex-start', gap: 8,
              marginBottom: 5, fontSize: '0.93rem', lineHeight: 1.65,
            }}>
              <span style={{ color: '#38bdf8', flexShrink: 0, marginTop: 2, fontWeight: 700 }}>▸</span>
              <span style={{ color: '#cbd5e1' }}>{inlineMd(it)}</span>
            </li>
          ))}
        </ul>
      );
      continue;
    }

    // Numbered list block — numéros orange
    if (line.match(/^\d+[.)]\s+/)) {
      const items = [];
      while (i < lines.length && lines[i].match(/^\d+[.)]\s+/)) {
        items.push(lines[i].replace(/^\d+[.)]\s+/, ''));
        i++;
      }
      out.push(
        <ol key={`ol${i}`} style={{ margin: '6px 0 8px', paddingLeft: 0, listStyle: 'none' }}>
          {items.map((it, j) => (
            <li key={j} style={{
              display: 'flex', alignItems: 'flex-start', gap: 8,
              marginBottom: 5, fontSize: '0.93rem', lineHeight: 1.65,
            }}>
              <span style={{
                color: '#f97316', flexShrink: 0, fontWeight: 800,
                minWidth: 22, fontSize: '0.88rem', marginTop: 2,
              }}>{j + 1}.</span>
              <span style={{ color: '#cbd5e1' }}>{inlineMd(it)}</span>
            </li>
          ))}
        </ol>
      );
      continue;
    }

    // Horizontal rule — discret avec lueur
    if (line.match(/^[-─═*]{3,}$/)) {
      out.push(
        <div key={`hr${i}`} style={{
          height: 1, margin: '14px 0',
          background: 'linear-gradient(90deg,transparent,rgba(56,189,248,0.25),rgba(249,115,22,0.2),transparent)',
        }} />
      );
      i++; continue;
    }

    // Empty line
    if (!line.trim()) {
      out.push(<div key={`br${i}`} style={{ height: 6 }} />);
      i++; continue;
    }

    // Normal paragraph
    out.push(
      <p key={`p${i}`} style={{ margin: '3px 0', color: '#cbd5e1', fontSize: '0.93rem', lineHeight: 1.65 }}>
        {inlineMd(line)}
      </p>
    );
    i++;
  }
  return <>{out}</>;
}

