// ─────────────────────────────────────────────────────────────────────────────
// COMPOSANT PRINCIPAL
// Props:
//   user          — utilisateur connecté
//   fileUrl       — URL d'un fichier à télécharger automatiquement au montage
//   autoAction    — clé d'action à déclencher automatiquement ('resume'|'quiz'|...)
//   style         — styles inline supplémentaires pour le conteneur
// ─────────────────────────────────────────────────────────────────────────────
export default function UnifiedAI({ user, fileUrl: initialFileUrl, fileObject: initialFileObject, autoAction, persistKey, style = {} }) {
  const [file, setFile]           = useState(null);
  const [fileName, setFileName]   = useState('');
  const [messages, setMessages]   = useState([]);
  const [input, setInput]         = useState('');
  const [loading, setLoading]     = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [pendingAction, setPendingAction] = useState(null); // action en attente si fichier introuvable
  const [corrigeMode, setCorrigeMode] = useState(false);   // mode : attente de l'épreuve à corriger
  const [exportData, setExportData] = useState(null);       // { content, actionKey } pour ExportModal

  const fileInputRef       = useRef(null);
  const cameraInputRef     = useRef(null);
  const examInputRef       = useRef(null);
  const examCameraInputRef = useRef(null);
  const bottomRef      = useRef(null);
  const contextHistory = useRef([]); // Mémoire de la conversation
  const courseCtxRef   = useRef(null); // { name, history } du cours courant pour le corrigé
  const lastLoadedUrl  = useRef(null); // URL du dernier fichier chargé (évite double-déclenchement)
  const retryFn        = useRef(null); // Dernière requête IA échouée — permet le bouton "Réessayer"
  const [pythonOk, setPythonOk] = useState(null); // null=vérif, true=ok, false=down
  const [activeFileUrl, setActiveFileUrl] = useState(null); // URL du fichier actif (mobile sans blob)

  // Clé localStorage pour persister l'historique de ce cours
  const storageKey = persistKey
    ? `revisia_ai_hist_${persistKey.replace(/[^a-zA-Z0-9]/g, '_').slice(0, 60)}`
    : null;

  // Auto-scroll
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, loading]);

  // ── Vérification santé du service Python au démarrage ────────────────────
  useEffect(() => {
    const AI_URL = process.env.REACT_APP_AI_SERVICE_URL || 'http://localhost:8001/api/v1';
    const isLocal = isRunningLocally();
    if (!isLocal) { setPythonOk(true); return; } // En prod : pas de check direct localhost
    fetch(`${AI_URL}/health`, { signal: AbortSignal.timeout(4000) })
      .then(r => setPythonOk(r.ok))
      .catch(() => setPythonOk(false));
  }, []);

  // ── Restauration de l'historique depuis localStorage (au montage) ─────────
  useEffect(() => {
    if (!storageKey) return;
    try {
      const saved = localStorage.getItem(storageKey);
      if (saved) {
        const { msgs, ctx } = JSON.parse(saved);
        if (msgs?.length > 0) {
          setMessages(msgs);
          contextHistory.current = ctx || [];
        }
      }
    } catch { /* ignore */ }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); // Une seule fois au montage — storageKey ne change pas

  // ── Sauvegarde de l'historique après chaque nouveau message ──────────────
  useEffect(() => {
    if (!storageKey || messages.length === 0) return;
    try {
      localStorage.setItem(storageKey, JSON.stringify({
        msgs: messages.slice(-30),         // garder les 30 derniers messages
        ctx: contextHistory.current.slice(-16), // 16 échanges de contexte
      }));
    } catch { /* ignore (localStorage plein) */ }
  }, [messages, storageKey]);

  // ── Chargement d'un File object local (cours en attente de sync) ────────────
  useEffect(() => {
    if (!initialFileObject) return;
    loadFile(initialFileObject, autoAction || null);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialFileObject]);

  // ── Chargement automatique depuis une URL (cours importé) ─────────────────
  useEffect(() => {
    if (!initialFileUrl) return;
    if (lastLoadedUrl.current === initialFileUrl) return; // même URL → ne pas recharger
    lastLoadedUrl.current = initialFileUrl;
    // Si déjà un historique en localStorage → ne pas recharger le fichier
    if (storageKey) {
      try {
        const saved = localStorage.getItem(storageKey);
        if (saved) {
          const { msgs } = JSON.parse(saved);
          if (msgs?.length > 0) return;
        }
      } catch { /* ignore */ }
    }

    // ── Mobile (Capacitor) : fetch CORS impossible → passer l'URL au service Python ──
    if (IS_NATIVE_APP) {
      const name = decodeURIComponent(initialFileUrl.split('/').pop().split('?')[0]) || 'document.pdf';
      setFileName(name);
      setActiveFileUrl(initialFileUrl);
      if (storageKey) { try { localStorage.removeItem(storageKey); } catch { /* ignore */ } }
      contextHistory.current = [];

      const action = autoAction ? ACTIONS.find(a => a.key === autoAction) : null;
      if (action) {
        const actionPrompt = action.prompt(name);
        setMessages([{ role: 'user', text: `▶ ${action.label} de "${name}"` }]);
        contextHistory.current.push({ role: 'user', text: actionPrompt });
        setTimeout(() => {
          const fd = new FormData();
          fd.append('question', actionPrompt);
          fd.append('file_url', initialFileUrl); // Python télécharge server-side
          setLoading(true);
          aiAPI.chat(fd)
            .then(res => {
              const txt = res.data?.answer || res.data?.text || res.data?.summary || '❌ Erreur.';
              setMessages(prev => [...prev, { role: 'ai', text: txt, actionKey: autoAction }]);
              contextHistory.current.push({ role: 'ai', text: txt });
            })
            .catch(() => {
              const urlAction = action;
              const urlName = name;
              retryFn.current = () => {
                const fd2 = new FormData();
                fd2.append('question', urlAction.prompt(urlName));
                fd2.append('file_url', initialFileUrl);
                setLoading(true);
                setMessages(prev => [...prev, { role: 'user', text: `▶ Nouvelle tentative : ${urlAction.label}` }]);
                aiAPI.chat(fd2)
                  .then(res2 => {
                    const txt2 = res2.data?.answer || res2.data?.text || res2.data?.summary || '❌ Erreur.';
                    setMessages(prev => [...prev, { role: 'ai', text: txt2, actionKey: autoAction }]);
                  })
                  .catch(() => setMessages(prev => [...prev, { role: 'ai', text: '❌ Toujours indisponible. Réessayez plus tard.', retryable: true }]))
                  .finally(() => setLoading(false));
              };
              setMessages(prev => [...prev, {
                role: 'ai',
                text: '❌ **Analyse impossible pour le moment.**\n\nVérifiez votre connexion et appuyez sur **Réessayer**.',
                retryable: true,
              }]);
            })
            .finally(() => setLoading(false));
        }, 50);
      } else {
        setMessages([{
          role: 'ai',
          text: `📎 **${name}** chargé.\n\nChoisissez une action ci-dessus ou posez votre question.`,
        }]);
      }
      return;
    }

    // ── Web : télécharger le fichier en blob (fetch normal) ──
    // ✅ Fix CORS : ne jamais envoyer le JWT à Cloudinary ou tout CDN externe
    const isBackendUrl = !initialFileUrl.startsWith('http') ||
                         initialFileUrl.includes('revisia-backend') ||
                         initialFileUrl.includes('localhost:8080') ||
                         initialFileUrl.includes('127.0.0.1:8080');
    const token = isBackendUrl ? localStorage.getItem('token') : null;
    fetch(initialFileUrl, { headers: token ? { Authorization: `Bearer ${token}` } : {} })
      .then(r => r.ok ? r.blob() : null)
      .then(blob => {
        if (!blob) {
          if (autoAction) setPendingAction(autoAction);
          const actionLabels = { resume: 'Résumé', quiz: 'Quiz', analyse: 'Analyser', exercices: 'Exercices', corrige: 'Corrigé' };
          const actionLabel = autoAction ? `**${actionLabels[autoAction] || autoAction}**` : null;
          setMessages([{ role: 'ai', text:
            `⚠️ **Fichier introuvable**\n\n` +
            `Ce cours n'est plus accessible sur le serveur (supprimé ou lien expiré).\n\n` +
            `📎 **Glissez votre fichier ici**` +
            (actionLabel ? ` — l'action ${actionLabel} se déclenchera automatiquement` : '') +
            `.\n\n💡 Ou **supprimez et ré-importez ce cours** pour le restaurer.`
          }]);
          return;
        }
        const name = decodeURIComponent(initialFileUrl.split('/').pop()) || 'document.pdf';
        const f = new File([blob], name, { type: blob.type || 'application/pdf' });
        loadFile(f, autoAction);
      })
      .catch(() => {
        if (autoAction) setPendingAction(autoAction);
        setMessages([{ role: 'ai', text: '📡 Fichier inaccessible. Glissez-le ici pour continuer.' }]);
      });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialFileUrl]);

  // ── Chargement d'un nouveau fichier ──────────────────────────────────────
  const loadFile = useCallback(async (f, actionKey = null) => {
    if (!f) return;
    const originalName = f.name || 'document';

    // ── Lire immédiatement le contenu (évite l'expiration du content:// URI Android) ──
    const stable = await stabiliserFichier(f);

    // Compresser les images avant tout envoi à l'IA
    // Photo caméra Android typique : 6 Mo → 350 Ko (×17 plus rapide sur 3G)
    const compressed = await compressImage(stable, { maxKB: 700 });

    setActiveFileUrl(null);
    const effectiveAction = actionKey || pendingAction;
    setPendingAction(null);
    if (storageKey) { try { localStorage.removeItem(storageKey); } catch { /* ignore */ } }
    const size = (compressed.size / 1024).toFixed(0);
    setFile(compressed);
    setFileName(originalName);
    contextHistory.current = [];

    if (effectiveAction === 'corrige') {
      courseCtxRef.current = { name: originalName, history: [] };
      setCorrigeMode(true);
      setMessages([{
        role: 'ai',
        text:
          `📚 Cours **"${originalName}"** chargé comme référence.\n\n` +
          `📎 **Envoyez maintenant l'épreuve ou l'exercice à corriger** ` +
          `(PDF, Word, photo de copie…)\n\n` +
          `Je générerai un corrigé complet basé sur le contenu de ce cours.`,
      }]);
    } else if (effectiveAction) {
      const action = ACTIONS.find(a => a.key === effectiveAction);
      if (action) {
        const actionPrompt = action.prompt(originalName);
        setMessages([{ role: 'user', text: `▶ ${action.label} de "${originalName}"` }]);
        contextHistory.current.push({ role: 'user', text: actionPrompt });
        setTimeout(() => {
          const fd = new FormData();
          fd.append('question', actionPrompt);
          fd.append('file', compressed, originalName);
          setLoading(true);
          aiAPI.chat(fd)
            .then(res => {
              const txt = res.data?.answer || res.data?.text || res.data?.summary || '❌ Erreur.';
              setMessages(prev => [...prev, { role: 'ai', text: txt, actionKey: effectiveAction }]);
              contextHistory.current.push({ role: 'ai', text: txt });
              courseCtxRef.current = { name: originalName, history: [{ role: 'user', text: actionPrompt }, { role: 'ai', text: txt }] };
            })
            .catch(err => {
              const st = err?.response?.status;
              const isDown = err?.code === 'ERR_NETWORK' || !st ||
                             st === 502 || st === 503 || st === 504 || st === 408;
              const isLocal = isRunningLocally();
              if (isDown && isLocal) setPythonOk(false);
              retryFn.current = () => loadFile(f, effectiveAction);
              const errMsg = isDown
                ? isLocal
                  ? '📡 **Service IA hors ligne (local)**\n\nLancez le service Python :\n```\npython simple_ai_server.py\n```\nPuis réessayez.'
                  : '❌ **Analyse impossible pour le moment.**\n\nVérifiez votre connexion et appuyez sur **Réessayer**.'
                : '❌ **Erreur lors de l\'analyse.** Réessayez.';
              setMessages(prev => [...prev, { role: 'ai', text: errMsg, retryable: true }]);
            })
            .finally(() => setLoading(false));
        }, 50);
      }
    } else {
      setMessages([{
        role: 'ai',
        text: `✅ **${originalName}** chargé (${size} Ko)\n\nChoisissez une action ci-dessus, ou posez directement votre question.`,
      }]);
    }
  }, [pendingAction, storageKey]);

  // ── Drag & Drop ───────────────────────────────────────────────────────────
  const onDrop = useCallback((e) => {
    e.preventDefault(); setIsDragging(false);
    const f = e.dataTransfer.files?.[0];
    if (!f) return;
    if (corrigeMode) {
      loadExamForCorrige(f); // En mode corrigé, le fichier glissé = l'épreuve
    } else {
      loadFile(f);
    }
  }, [loadFile, corrigeMode]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Envoi d'un message / déclenchement d'une action ──────────────────────
  const send = useCallback(async (prompt, displayText = null) => {
    if (!prompt?.trim() || loading) return;

    const userDisplay = displayText || prompt;
    const userMsg = { role: 'user', text: userDisplay };
    setMessages(prev => [...prev, userMsg]);
    contextHistory.current.push({ role: 'user', text: prompt });
    setLoading(true);

    try {
      // Contexte des 6 derniers échanges (pour les questions de suivi)
      const context = contextHistory.current
        .slice(-7, -1)
        .map(m => `${m.role === 'user' ? 'Étudiant' : 'IA'}: ${m.text.slice(0, 600)}`)
        .join('\n\n');

      const fullPrompt = context
        ? `Contexte de la conversation précédente:\n${context}\n\n---\n\nNouvelle demande: ${prompt}`
        : prompt;

      const fd = new FormData();
      fd.append('question', fullPrompt);
      if (file) fd.append('file', file);
      else if (IS_NATIVE_APP && activeFileUrl) fd.append('file_url', activeFileUrl);

      const res = await aiAPI.chat(fd);
      const aiText =
        res.data?.answer || res.data?.text ||
        res.data?.summary || res.data?.correction ||
        (typeof res.data === 'string' ? res.data : '❌ Réponse invalide.');

      // ✅ Pas d'actionKey pour les messages libres (export = type "Document")
      const aiMsg = { role: 'ai', text: aiText };
      setMessages(prev => [...prev, aiMsg]);
      contextHistory.current.push({ role: 'ai', text: aiText });
    } catch (err) {
      const st = err?.response?.status;
      const netErr = err?.code === 'ERR_NETWORK' || !st ||
                     st === 502 || st === 503 || st === 504 || st === 408;
      const isLocal = isRunningLocally();
      if (netErr && isLocal) setPythonOk(false);
      const errMsg = netErr
        ? isLocal
          ? '📡 **Service IA hors ligne (local)**\n\nLancez le service Python dans votre terminal :\n```\npython simple_ai_server.py\n```\nPuis réessayez.'
          : '❌ **Analyse impossible pour le moment.** Réessayez.'
        : '❌ Erreur lors de la génération. Réessayez.';
      setMessages(prev => [...prev, { role: 'ai', text: errMsg }]);
    } finally {
      setLoading(false);
    }
  }, [file, loading, activeFileUrl]);

  // ── Clic sur bouton "Corrigé" avec un fichier cours déjà chargé ──────────
  const handleCorrigeClick = useCallback(() => {
    const hasFile = file || (IS_NATIVE_APP && activeFileUrl);
    if (!hasFile) {
      // Aucun fichier : demander d'envoyer l'épreuve directement
      setPendingAction('corrige');
      setMessages([{
        role: 'ai',
        text: '📎 **Corrigé** : Envoyez l\'épreuve ou l\'exercice à corriger (PDF, Word, image…).',
      }]);
      return;
    }
    // Cours chargé (blob ou URL mobile) → sauvegarder le contexte, entrer en mode corrigé
    const refName = fileName || 'cours';
    courseCtxRef.current = {
      name: refName,
      history: contextHistory.current.slice(-8),
    };
    setCorrigeMode(true);
    setMessages(prev => [...prev, {
      role: 'ai',
      text:
        `📚 Cours **"${refName}"** conservé comme référence.\n\n` +
        `📎 **Envoyez maintenant l'épreuve à corriger** (PDF, Word, photo…)\n\n` +
        `Je génèrerai un corrigé complet basé sur votre cours.`,
    }]);
  }, [file, fileName, activeFileUrl]);

  // ── Chargement de l'épreuve en mode corrigé ──────────────────────────────
  const loadExamForCorrige = useCallback(async (examFile) => {
    const examName = examFile.name || 'épreuve';
    // Lire immédiatement (content:// Android expire)
    const stable = await stabiliserFichier(examFile);
    // Compresser si c'est une photo de copie (scan ou caméra)
    const compressed = await compressImage(stable, { maxKB: 700 });

    const ctx = courseCtxRef.current;
    const ctxLines = (ctx?.history || [])
      .filter(m => m.role === 'ai')
      .map(m => m.text.slice(0, 700))
      .join('\n\n');

    const examPrompt =
      `Ce document joint est une ÉPREUVE ou un EXERCICE à corriger` +
      (ctx?.name ? ` basé sur le cours "${ctx.name}"` : '') + `.\n\n` +
      (ctxLines ? `Contexte du cours :\n${ctxLines}\n\n` : '') +
      `Génère un CORRIGÉ TYPE COMPLET de cette épreuve en français :\n` +
      `- Réponses à toutes les questions avec justifications (basées sur le cours)\n` +
      `- Démonstrations et calculs détaillés si applicable\n` +
      `- Barème indicatif par question\n` +
      `Sois précis, pédagogique et exhaustif.`;

    setCorrigeMode(false);
    setMessages(prev => [...prev, {
      role: 'user',
      text: `📝 Correction de **"${examName}"**${ctx?.name ? ` — basée sur "${ctx.name}"` : ''}`,
    }]);
    contextHistory.current.push({ role: 'user', text: `Correction de ${examName}` });
    setLoading(true);

    const fd = new FormData();
    fd.append('question', examPrompt);
    fd.append('file', compressed, examName);

    aiAPI.chat(fd)
      .then(res => {
        const txt = res.data?.answer || res.data?.text || res.data?.summary || '❌ Erreur.';
        setMessages(prev => [...prev, { role: 'ai', text: txt }]);
        contextHistory.current.push({ role: 'ai', text: txt });
      })
      .catch(err => {
        const st = err?.response?.status;
        const netErr = err?.code === 'ERR_NETWORK' || !st ||
                       st === 502 || st === 503 || st === 504 || st === 408;
        const isLocal = isRunningLocally();
        if (netErr && isLocal) setPythonOk(false);
        const errMsg = netErr
          ? isLocal
            ? '📡 **Service IA hors ligne (local)**\n\nLancez le service Python :\n```\npython simple_ai_server.py\n```\nPuis réessayez.'
            : '❌ **Analyse impossible pour le moment.** Réessayez.'
          : '❌ Erreur lors de la correction.';
        setMessages(prev => [...prev, { role: 'ai', text: errMsg }]);
      })
      .finally(() => setLoading(false));
  }, []);

  const handleSend = useCallback(() => {
    const q = input.trim();
    if (!q) return;
    setInput('');
    send(q);
  }, [input, send]);

  const reset = useCallback(() => {
    setFile(null); setFileName(''); setActiveFileUrl(null);
    setMessages([]); setInput('');
    setPendingAction(null);
    setCorrigeMode(false);
    contextHistory.current = [];
    courseCtxRef.current = null;
    if (storageKey) { try { localStorage.removeItem(storageKey); } catch { /* ignore */ } }
  }, [storageKey]);

  // ─────────────────────────────────────────────────────────────────────────
  // RENDU
  // ─────────────────────────────────────────────────────────────────────────
  return (
    <div style={{
      display: 'flex', flexDirection: 'column',
      height: '100%', minHeight: 0,
      background: 'linear-gradient(180deg, #07101E 0%, #090e1c 100%)',
      borderRadius: 20,
      border: '1px solid rgba(56,189,248,0.12)',
      boxShadow: '0 25px 50px -12px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.04)',
      overflow: 'hidden', fontFamily: 'inherit',
      ...style,
    }}>

      {/* ── HEADER ──────────────────────────────────────────────────── */}
      <div style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        padding: '13px 16px',
        background: 'linear-gradient(135deg, #0d1f3c 0%, #0a1628 100%)',
        borderBottom: '1px solid rgba(56,189,248,0.1)',
        flexShrink: 0, position: 'relative', overflow: 'hidden',
      }}>
        <div style={{
          position: 'absolute', top: -40, left: -20, width: 140, height: 140,
          borderRadius: '50%',
          background: 'radial-gradient(circle, rgba(56,189,248,0.07) 0%, transparent 70%)',
          pointerEvents: 'none',
        }} />
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, position: 'relative', zIndex: 1 }}>
          <div style={{
            width: 34, height: 34, borderRadius: '50%', flexShrink: 0,
            background: 'linear-gradient(135deg, rgba(56,189,248,0.18), rgba(14,165,233,0.08))',
            border: '1.5px solid rgba(56,189,248,0.3)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            boxShadow: '0 0 16px rgba(56,189,248,0.18)',
          }}>
            <Sparkles size={16} color="#38BDF8" />
          </div>
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 7 }}>
              <span style={{
                background: 'linear-gradient(135deg, #7DD3FC, #38BDF8)',
                WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent',
                backgroundClip: 'text',
                fontWeight: 800, fontSize: '0.95rem', letterSpacing: '-0.01em',
              }}>
                Assistant IA
              </span>
              {fileName && (
                <span style={{
                  background: 'rgba(56,189,248,0.1)', color: '#7DD3FC',
                  fontSize: '0.68rem', fontWeight: 600, padding: '2px 8px',
                  borderRadius: 20, border: '1px solid rgba(56,189,248,0.18)',
                  maxWidth: 160, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                }}>
                  {FILE_ICON(fileName)} {fileName}
                </span>
              )}
            </div>
            {pythonOk === false && (
              <span title="Lancez : python simple_ai_server.py" style={{
                display: 'inline-flex', alignItems: 'center', gap: 4,
                background: 'rgba(239,68,68,0.1)', color: '#F87171',
                fontSize: '0.6rem', fontWeight: 700, padding: '1px 7px',
                borderRadius: 10, border: '1px solid rgba(239,68,68,0.22)', cursor: 'help',
              }}>
                <span style={{ width: 5, height: 5, borderRadius: '50%', background: '#F87171', display: 'inline-block' }} />
                IA hors ligne
              </span>
            )}
            {pythonOk === true && (
              <span style={{
                display: 'inline-flex', alignItems: 'center', gap: 4,
                background: 'rgba(16,185,129,0.08)', color: '#34D399',
                fontSize: '0.6rem', fontWeight: 700, padding: '1px 7px',
                borderRadius: 10, border: '1px solid rgba(16,185,129,0.18)',
              }}>
                <span style={{
                  width: 5, height: 5, borderRadius: '50%', background: '#34D399',
                  display: 'inline-block',
                  animation: 'aiStatusPulse 2.5s ease-in-out infinite',
                }} />
                IA prête
              </span>
            )}
          </div>
        </div>
        {(file || messages.length > 0) && (
          <button onClick={reset} style={{
            background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.07)',
            borderRadius: 8, cursor: 'pointer', color: '#64748B',
            display: 'flex', alignItems: 'center', gap: 5,
            fontSize: '0.71rem', fontWeight: 500, padding: '5px 10px',
            position: 'relative', zIndex: 1, transition: 'all 0.15s',
          }}
          onMouseEnter={e => { e.currentTarget.style.color = '#94A3B8'; e.currentTarget.style.borderColor = 'rgba(255,255,255,0.14)'; }}
          onMouseLeave={e => { e.currentTarget.style.color = '#64748B'; e.currentTarget.style.borderColor = 'rgba(255,255,255,0.07)'; }}
          >
            <RotateCcw size={11} /> Réinitialiser
          </button>
        )}
      </div>

      {/* ── ZONE UPLOAD (si pas de fichier, et pas d'URL active sur mobile) ── */}
      {!file && !(IS_NATIVE_APP && activeFileUrl) && (
        <>
          {pendingAction && (
            <div style={{
              margin: '12px 14px 0', borderRadius: 12,
              background: 'linear-gradient(135deg, rgba(56,189,248,0.07), rgba(14,165,233,0.04))',
              border: '1px solid rgba(56,189,248,0.22)', padding: '10px 14px',
            }}>
              <p style={{ margin: 0, color: '#38BDF8', fontSize: '0.8rem', fontWeight: 700 }}>
                ▶ Action en attente : {ACTIONS.find(a => a.key === pendingAction)?.label || pendingAction}
              </p>
              <p style={{ margin: '3px 0 0', color: '#7DD3FC', fontSize: '0.72rem' }}>
                Glissez votre fichier ci-dessous pour déclencher automatiquement.
              </p>
            </div>
          )}
          {pythonOk === false && isRunningLocally() && (
            <div style={{
              margin: '12px 14px 0', borderRadius: 12,
              background: 'rgba(239,68,68,0.05)', border: '1px solid rgba(239,68,68,0.18)',
              padding: '10px 14px',
            }}>
              <p style={{ margin: 0, color: '#F87171', fontSize: '0.78rem', fontWeight: 700 }}>
                ⚠️ Service IA hors ligne — lancez Python dans votre terminal.
              </p>
              <p style={{ margin: '4px 0 0', color: '#FCA5A5', fontSize: '0.72rem' }}>
                <code style={{
                  background: 'rgba(15,23,42,0.8)', color: '#7DD3FC',
                  padding: '2px 8px', borderRadius: 5, fontFamily: 'monospace',
                  border: '1px solid rgba(56,189,248,0.18)',
                }}>python simple_ai_server.py</code>
              </p>
            </div>
          )}
          <div
            onDrop={onDrop}
            onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
            onDragLeave={() => setIsDragging(false)}
            onClick={() => fileInputRef.current?.click()}
            style={{
              margin: '14px', borderRadius: 16,
              background: isDragging
                ? 'linear-gradient(135deg, rgba(56,189,248,0.1), rgba(14,165,233,0.06))'
                : 'linear-gradient(135deg, rgba(14,165,233,0.035), rgba(249,115,22,0.015))',
              border: `2px dashed ${isDragging ? '#38BDF8' : 'rgba(56,189,248,0.15)'}`,
              padding: '26px 20px 20px', textAlign: 'center', cursor: 'pointer',
              transition: 'all 0.25s ease', position: 'relative', overflow: 'hidden',
              boxShadow: isDragging ? '0 0 28px rgba(56,189,248,0.1) inset' : 'none',
            }}
          >
            <div style={{
              position: 'absolute', top: 0, left: '-100%',
              width: '60%', height: '100%',
              background: 'linear-gradient(90deg, transparent, rgba(56,189,248,0.04), transparent)',
              animation: 'aiShimmer 5s ease-in-out infinite', pointerEvents: 'none',
            }} />
            <div style={{
              width: 54, height: 54, borderRadius: '50%', margin: '0 auto 13px',
              background: isDragging
                ? 'linear-gradient(135deg, rgba(56,189,248,0.22), rgba(14,165,233,0.12))'
                : 'linear-gradient(135deg, rgba(56,189,248,0.08), rgba(14,165,233,0.04))',
              border: `2px solid ${isDragging ? 'rgba(56,189,248,0.5)' : 'rgba(56,189,248,0.16)'}`,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              boxShadow: isDragging ? '0 0 22px rgba(56,189,248,0.28)' : '0 0 10px rgba(56,189,248,0.06)',
              transition: 'all 0.25s ease',
            }}>
              <Upload size={22} color={isDragging ? '#38BDF8' : '#4A90C4'} />
            </div>
            <p style={{
              color: isDragging ? '#e0f2fe' : '#94A3B8',
              margin: 0, fontWeight: 700, fontSize: '0.9rem',
            }}>
              {isDragging ? 'Déposez votre fichier ici' : 'Glissez votre fichier ici'}
            </p>
            <p style={{ color: '#475569', margin: '4px 0 10px', fontSize: '0.74rem' }}>
              ou <span style={{ color: '#38BDF8', textDecoration: 'underline' }}>cliquez pour choisir</span>
            </p>
            <div style={{ display: 'flex', gap: 5, justifyContent: 'center', flexWrap: 'wrap', marginBottom: 12 }}>
              {['PDF', 'Word', 'Excel', 'PPT', 'Image'].map(t => (
                <span key={t} style={{
                  padding: '2px 8px', borderRadius: 20,
                  background: 'rgba(71,85,105,0.12)', border: '1px solid rgba(71,85,105,0.18)',
                  color: '#64748B', fontSize: '0.67rem', fontWeight: 600,
                }}>{t}</span>
              ))}
            </div>
            {/* Bouton caméra — stoppe la propagation pour ne pas ouvrir le sélecteur de fichiers */}
            <div onClick={e => e.stopPropagation()}>
              <label style={{
                display: 'inline-flex', alignItems: 'center', gap: 6,
                padding: '7px 14px', borderRadius: 20, cursor: 'pointer',
                background: 'rgba(56,189,248,0.08)', border: '1px solid rgba(56,189,248,0.25)',
                color: '#38BDF8', fontSize: '0.75rem', fontWeight: 700,
                transition: 'all 0.15s',
              }}>
                <input type="file" accept="image/*" capture="environment"
                  style={{ display: 'none' }}
                  onChange={e => e.target.files?.[0] && loadFile(e.target.files[0])} />
                <Camera size={14} /> Prendre une photo
              </label>
            </div>
            <input ref={fileInputRef} type="file" accept={ACCEPT} style={{ display: 'none' }}
              onChange={e => e.target.files?.[0] && loadFile(e.target.files[0])} />
          </div>
        </>
      )}

      {/* ── BOUTONS D'ACTIONS (si fichier chargé OU URL active sur mobile) ── */}
      {(file || (IS_NATIVE_APP && activeFileUrl)) && (
        <div style={{
          padding: '9px 12px 8px',
          borderBottom: '1px solid rgba(56,189,248,0.09)',
          background: 'rgba(12,26,50,0.5)',
          flexShrink: 0,
        }}>
          <div style={{
            display: 'flex', gap: 6, overflowX: 'auto', alignItems: 'center',
            scrollbarWidth: 'none', msOverflowStyle: 'none',
          }}>
            {ACTIONS.map(({ key, icon: Icon, label, color, prompt }) => (
              <button
                key={key}
                onClick={() =>
                  key === 'corrige'
                    ? handleCorrigeClick()
                    : send(prompt(fileName), `▶ ${label} de "${fileName}"`)
                }
                disabled={loading}
                style={{
                  display: 'flex', alignItems: 'center', gap: 6,
                  padding: '7px 14px', borderRadius: 24,
                  border: `1.5px solid ${corrigeMode && key === 'corrige' ? color : `${color}32`}`,
                  background: corrigeMode && key === 'corrige'
                    ? `linear-gradient(135deg, ${color}28, ${color}14)`
                    : `linear-gradient(135deg, ${color}10, ${color}05)`,
                  color: color, fontSize: '0.77rem', fontWeight: 700,
                  cursor: loading ? 'not-allowed' : 'pointer',
                  whiteSpace: 'nowrap', flexShrink: 0,
                  opacity: loading ? 0.5 : 1, transition: 'all 0.18s ease',
                  boxShadow: corrigeMode && key === 'corrige' ? `0 0 14px ${color}38` : 'none',
                }}
                onMouseEnter={e => {
                  if (!loading) {
                    e.currentTarget.style.background = `linear-gradient(135deg, ${color}22, ${color}10)`;
                    e.currentTarget.style.borderColor = `${color}58`;
                    e.currentTarget.style.boxShadow = `0 0 12px ${color}22`;
                    e.currentTarget.style.transform = 'translateY(-1px)';
                  }
                }}
                onMouseLeave={e => {
                  if (!loading) {
                    e.currentTarget.style.background = corrigeMode && key === 'corrige'
                      ? `linear-gradient(135deg, ${color}28, ${color}14)`
                      : `linear-gradient(135deg, ${color}10, ${color}05)`;
                    e.currentTarget.style.borderColor = corrigeMode && key === 'corrige' ? color : `${color}32`;
                    e.currentTarget.style.boxShadow = corrigeMode && key === 'corrige' ? `0 0 14px ${color}38` : 'none';
                    e.currentTarget.style.transform = 'translateY(0)';
                  }
                }}
              >
                <Icon size={13} /> {label}
                {corrigeMode && key === 'corrige' && (
                  <span style={{ fontSize: '0.62rem', opacity: 0.75 }}>⏳</span>
                )}
              </button>
            ))}
            <div style={{ width: 1, height: 18, background: 'rgba(71,85,105,0.25)', flexShrink: 0 }} />
            <button
              onClick={() => fileInputRef.current?.click()}
              style={{
                display: 'flex', alignItems: 'center', gap: 4,
                padding: '7px 11px', borderRadius: 24,
                border: '1px solid rgba(71,85,105,0.2)',
                background: 'rgba(71,85,105,0.06)', color: '#64748B',
                fontSize: '0.71rem', fontWeight: 500, cursor: 'pointer',
                whiteSpace: 'nowrap', flexShrink: 0, transition: 'all 0.15s',
              }}
              onMouseEnter={e => { e.currentTarget.style.color = '#94A3B8'; e.currentTarget.style.borderColor = 'rgba(71,85,105,0.38)'; }}
              onMouseLeave={e => { e.currentTarget.style.color = '#64748B'; e.currentTarget.style.borderColor = 'rgba(71,85,105,0.2)'; }}
            >
              <Upload size={11} /> Changer
            </button>
            <label style={{
              display: 'flex', alignItems: 'center', gap: 4,
              padding: '7px 11px', borderRadius: 24,
              border: '1px solid rgba(56,189,248,0.25)',
              background: 'rgba(56,189,248,0.06)', color: '#38BDF8',
              fontSize: '0.71rem', fontWeight: 600, cursor: 'pointer',
              whiteSpace: 'nowrap', flexShrink: 0,
            }}>
              <input ref={cameraInputRef} type="file" accept="image/*" capture="environment"
                style={{ display: 'none' }}
                onChange={e => e.target.files?.[0] && loadFile(e.target.files[0])} />
              <Camera size={11} /> Photo
            </label>
            <input ref={fileInputRef} type="file" accept={ACCEPT} style={{ display: 'none' }}
              onChange={e => e.target.files?.[0] && loadFile(e.target.files[0])} />
          </div>
        </div>
      )}

      {/* ── ZONE UPLOAD ÉPREUVE (mode corrigé) ──────────────────────── */}
      {(file || (IS_NATIVE_APP && activeFileUrl)) && corrigeMode && (
        <div
          onDrop={e => { e.preventDefault(); const f = e.dataTransfer.files?.[0]; if (f) loadExamForCorrige(f); }}
          onDragOver={e => e.preventDefault()}
          onClick={() => examInputRef.current?.click()}
          style={{
            margin: '8px 12px',
            borderRadius: 12,
            background: 'linear-gradient(135deg, rgba(234,179,8,0.06), rgba(234,179,8,0.02))',
            border: '2px dashed rgba(234,179,8,0.32)',
            padding: '12px 16px', textAlign: 'center', cursor: 'pointer',
            transition: 'all 0.2s', flexShrink: 0,
          }}
          onMouseEnter={e => { e.currentTarget.style.borderColor = 'rgba(234,179,8,0.55)'; }}
          onMouseLeave={e => { e.currentTarget.style.borderColor = 'rgba(234,179,8,0.32)'; }}
        >
          <p style={{ color: '#EAB308', fontWeight: 700, margin: '0 0 2px', fontSize: '0.82rem' }}>
            📎 Glissez l'épreuve ici, ou cliquez pour choisir
          </p>
          <p style={{ color: '#B45309', margin: '0 0 10px', fontSize: '0.7rem' }}>
            PDF · Word · Image (photo de copie ou d'examen)
          </p>
          {/* Option caméra pour photographier la copie/examen */}
          <div onClick={e => e.stopPropagation()}>
            <label style={{
              display: 'inline-flex', alignItems: 'center', gap: 6,
              padding: '6px 13px', borderRadius: 20, cursor: 'pointer',
              background: 'rgba(234,179,8,0.1)', border: '1px solid rgba(234,179,8,0.35)',
              color: '#EAB308', fontSize: '0.73rem', fontWeight: 700,
            }}>
              <input ref={examCameraInputRef} type="file" accept="image/*" capture="environment"
                style={{ display: 'none' }}
                onChange={e => { const f = e.target.files?.[0]; if (f) loadExamForCorrige(f); }} />
              <Camera size={13} /> Photographier la copie
            </label>
          </div>
          <input ref={examInputRef} type="file" accept={ACCEPT} style={{ display: 'none' }}
            onChange={e => { const f = e.target.files?.[0]; if (f) loadExamForCorrige(f); }} />
        </div>
      )}

      {/* ── MESSAGES ─────────────────────────────────────────────────── */}
      <div style={{
        flex: 1, overflowY: 'auto', padding: '14px',
        display: 'flex', flexDirection: 'column', gap: 10,
      }}>
        {/* État vide */}
        {messages.length === 0 && !file && (
          <div style={{ margin: 'auto', padding: '16px', textAlign: 'center', maxWidth: 272 }}>
            <div style={{
              width: 62, height: 62, borderRadius: '50%', margin: '0 auto 15px',
              background: 'linear-gradient(135deg, rgba(56,189,248,0.1), rgba(249,115,22,0.05))',
              border: '2px solid rgba(56,189,248,0.14)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              boxShadow: '0 0 20px rgba(56,189,248,0.07)',
            }}>
              <Sparkles size={26} color="#38BDF8" style={{ opacity: 0.7 }} />
            </div>
            <p style={{ margin: '0 0 6px', fontWeight: 800, color: '#CBD5E1', fontSize: '0.95rem' }}>
              Prêt à analyser
            </p>
            <p style={{ margin: '0 0 16px', fontSize: '0.76rem', color: '#475569', lineHeight: 1.6 }}>
              Importez un document et l'IA lira son contenu réel pour vous aider
            </p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 5 }}>
              {[
                { icon: '📝', label: 'Résumé structuré' },
                { icon: '🧠', label: 'Quiz automatique' },
                { icon: '🔍', label: 'Analyse profonde' },
                { icon: '✏️', label: 'Corrigé complet' },
              ].map(f => (
                <div key={f.label} style={{
                  display: 'flex', alignItems: 'center', gap: 9,
                  padding: '6px 11px', borderRadius: 8, textAlign: 'left',
                  background: 'rgba(30,41,59,0.35)', border: '1px solid rgba(56,189,248,0.06)',
                }}>
                  <span style={{ fontSize: '0.83rem' }}>{f.icon}</span>
                  <span style={{ color: '#64748B', fontSize: '0.74rem', fontWeight: 600 }}>{f.label}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Bulles de messages */}
        {messages.map((msg, idx) => (
          <div key={idx} style={{
            display: 'flex',
            justifyContent: msg.role === 'user' ? 'flex-end' : 'flex-start',
            alignItems: 'flex-start', gap: 8,
          }}>
            {msg.role === 'ai' && (
              <div style={{
                width: 30, height: 30, borderRadius: '50%', flexShrink: 0, marginTop: 1,
                background: 'linear-gradient(135deg, #0d2040, #142d52)',
                border: '1.5px solid rgba(56,189,248,0.28)',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                boxShadow: '0 0 12px rgba(56,189,248,0.1)',
              }}>
                <Sparkles size={13} color="#38BDF8" />
              </div>
            )}
            <div style={{
              maxWidth: '84%',
              background: msg.role === 'user'
                ? 'linear-gradient(135deg, rgba(249,115,22,0.18), rgba(249,115,22,0.1))'
                : 'rgba(14,165,233,0.055)',
              border: `1px solid ${msg.role === 'user'
                ? 'rgba(249,115,22,0.27)'
                : 'rgba(56,189,248,0.13)'}`,
              borderLeft: msg.role === 'ai' ? '3px solid rgba(14,165,233,0.32)' : undefined,
              boxShadow: msg.role === 'ai' ? '0 2px 8px rgba(0,0,0,0.12)' : undefined,
              borderRadius: msg.role === 'user' ? '16px 16px 4px 16px' : '4px 16px 16px 16px',
              padding: msg.role === 'ai' ? '12px 15px 8px' : '10px 14px',
            }}>
              {msg.role === 'ai'
                ? <>
                    <MarkdownMsg text={msg.text} />
                    {msg.retryable && retryFn.current && (
                      <button
                        onClick={() => { retryFn.current(); }}
                        style={{
                          marginTop: 8,
                          display: 'flex', alignItems: 'center', gap: 5,
                          background: 'rgba(56,189,248,0.08)',
                          border: '1px solid rgba(56,189,248,0.22)',
                          borderRadius: 7, padding: '5px 12px',
                          color: '#38BDF8', fontSize: '0.73rem', fontWeight: 700,
                          cursor: 'pointer', transition: 'all .15s',
                        }}
                        onMouseEnter={e => { e.currentTarget.style.background = 'rgba(56,189,248,0.18)'; }}
                        onMouseLeave={e => { e.currentTarget.style.background = 'rgba(56,189,248,0.08)'; }}
                      >
                        <RotateCcw size={12} /> Réessayer
                      </button>
                    )}
                    {msg.text && msg.text.length > 180 && !msg.text.startsWith('⚠️') && !msg.text.startsWith('📡') && !msg.text.startsWith('📚') && (
                      <button
                        onClick={() => setExportData({ content: msg.text, actionKey: msg.actionKey || null })}
                        style={{
                          marginTop: 9,
                          display: 'flex', alignItems: 'center', gap: 5,
                          background: 'rgba(56,189,248,0.06)',
                          border: '1px solid rgba(56,189,248,0.13)',
                          borderRadius: 7, padding: '4px 11px',
                          color: '#0284c7', fontSize: '0.72rem', fontWeight: 600,
                          cursor: 'pointer', transition: 'all .15s',
                        }}
                        onMouseEnter={e => { e.currentTarget.style.background = 'rgba(56,189,248,0.13)'; e.currentTarget.style.borderColor = 'rgba(56,189,248,0.28)'; }}
                        onMouseLeave={e => { e.currentTarget.style.background = 'rgba(56,189,248,0.06)'; e.currentTarget.style.borderColor = 'rgba(56,189,248,0.13)'; }}
                      >
                        <Download size={12} />
                        Exporter PDF / Word
                      </button>
                    )}
                  </>
                : <span style={{ color: '#CBD5E1', fontSize: '0.93rem', lineHeight: 1.5 }}>{msg.text}</span>
              }
            </div>
          </div>
        ))}

        {/* Indicateur de chargement */}
        {loading && (
          <div style={{ display: 'flex', alignItems: 'flex-start', gap: 8 }}>
            <div style={{
              width: 30, height: 30, borderRadius: '50%', flexShrink: 0, marginTop: 1,
              background: 'linear-gradient(135deg, #0d2040, #142d52)',
              border: '1.5px solid rgba(56,189,248,0.28)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              boxShadow: '0 0 12px rgba(56,189,248,0.1)',
            }}>
              <Loader size={13} color="#38BDF8" style={{ animation: 'aiSpin 1s linear infinite' }} />
            </div>
            <div style={{
              background: 'rgba(14,165,233,0.055)',
              border: '1px solid rgba(56,189,248,0.13)',
              borderLeft: '3px solid rgba(14,165,233,0.32)',
              borderRadius: '4px 16px 16px 16px',
              padding: '12px 16px',
              display: 'flex', alignItems: 'center', gap: 5,
            }}>
              {[0, 1, 2].map(d => (
                <span key={d} style={{
                  width: 7, height: 7, borderRadius: '50%',
                  background: '#38BDF8',
                  animation: `aiDot 1.4s ease-in-out ${d * 0.18}s infinite`,
                  display: 'inline-block',
                }} />
              ))}
            </div>
          </div>
        )}
        <div ref={bottomRef} />
      </div>

      {/* ── ZONE DE SAISIE ──────────────────────────────────────────── */}
      <div style={{
        padding: '10px 12px 11px',
        borderTop: '1px solid rgba(56,189,248,0.09)',
        background: 'linear-gradient(180deg, rgba(12,26,50,0.8) 0%, rgba(10,22,44,0.95) 100%)',
        display: 'flex', gap: 8, alignItems: 'flex-end', flexShrink: 0,
      }}>
        <textarea
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={e => {
            if (e.key === 'Enter' && !e.shiftKey) {
              e.preventDefault();
              handleSend();
            }
          }}
          placeholder={
            corrigeMode
              ? "Glissez l'épreuve ci-dessus, ou posez une question sur le cours…"
              : file
                ? `Posez une question sur "${fileName}"...`
                : 'Importez un fichier ou posez une question générale...'
          }
          rows={1}
          style={{
            flex: 1, background: 'rgba(255,255,255,0.04)',
            border: '1.5px solid rgba(56,189,248,0.16)', borderRadius: 12,
            color: '#e2e8f0', padding: '9px 14px', fontSize: '0.85rem',
            resize: 'none', outline: 'none', lineHeight: 1.5,
            maxHeight: 110, overflowY: 'auto', fontFamily: 'inherit',
            transition: 'border-color 0.15s',
          }}
          onFocus={e => { e.target.style.borderColor = 'rgba(56,189,248,0.38)'; }}
          onBlur={e => { e.target.style.borderColor = 'rgba(56,189,248,0.16)'; }}
        />
        <button
          onClick={handleSend}
          disabled={loading || !input.trim()}
          style={{
            background: (input.trim() && !loading)
              ? 'linear-gradient(135deg, #38BDF8, #0284c7)'
              : 'rgba(56,189,248,0.09)',
            border: 'none', borderRadius: 12, padding: '9px 13px',
            cursor: (input.trim() && !loading) ? 'pointer' : 'not-allowed',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            transition: 'all 0.2s', flexShrink: 0,
            boxShadow: (input.trim() && !loading) ? '0 4px 14px rgba(56,189,248,0.28)' : 'none',
          }}
        >
          <Send size={16} color={(input.trim() && !loading) ? '#0F172A' : '#475569'} />
        </button>
      </div>

      <style>{`
        @keyframes aiSpin  { to { transform: rotate(360deg); } }
        @keyframes aiDot {
          0%, 80%, 100% { transform: translateY(0); opacity: 0.35; }
          40% { transform: translateY(-7px); opacity: 1; }
        }
        @keyframes aiStatusPulse {
          0%, 100% { box-shadow: 0 0 5px rgba(52,211,153,0.7); }
          50% { box-shadow: 0 0 10px rgba(52,211,153,0.3); opacity: 0.6; }
        }
        @keyframes aiShimmer {
          0% { left: -100%; }
          60%, 100% { left: 200%; }
        }
      `}</style>

      {/* ── Modal Export PDF / Word ── */}
      {exportData && (
        <ExportModal
          content={exportData.content}
          actionKey={exportData.actionKey}
          fileName={fileName}
          onClose={() => setExportData(null)}
        />
      )}
    </div>
  );
}
