import React, { useState, useEffect, useCallback } from 'react';
import { Sparkles, X, Crown, Zap } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import UnifiedAI from './UnifiedAI';
import PointsManager from './PointsManager';
import { pushBackHandler } from '../utils/backHandler';

/**
 * Bouton IA flottant — StudentDashboard, DéleguéDashboard, etc.
 * • Étudiant avec abonnement/points → ouvre l'AILab complet.
 * • Étudiant sans accès              → ouvre le PointsManager.
 * • Admin/Délégué/autre              → accès libre.
 * Usage : <FloatingAIAssistant user={user} />
 */
const FloatingAIAssistant = ({ user }) => {
  const [open, setOpen]           = useState(false);
  const [showPoints, setShowPoints] = useState(false);
  const [statutIA, setStatutIA]   = useState(null);

  const isEtudiantRole = user?.role === 'ETUDIANT' || user?.role === 'DELEGUE';

  /* Charger le statut IA via axios direct (évite l'intercepteur 401→logout) */
  const fetchStatut = useCallback(() => {
    if (!isEtudiantRole) return;
    const token = localStorage.getItem('token');
    if (!token) return;
    import('axios').then(({ default: axios }) => {
      axios.get(
        `${process.env.REACT_APP_API_URL || 'http://localhost:8080/api'}/paiements/statut-ia`,
        { headers: { Authorization: `Bearer ${token}` } }
      )
        .then(r => setStatutIA(r.data))
        .catch(() => setStatutIA(null));
    });
  }, [isEtudiantRole]);

  useEffect(() => { fetchStatut(); }, [fetchStatut]);

  // Bouton RETOUR Android : ferme PointsManager puis overlay IA
  useEffect(() => {
    const off = pushBackHandler(() => {
      if (showPoints) { setShowPoints(false); fetchStatut(); return true; }
      if (open) { setOpen(false); return true; }
      return false;
    });
    return off;
  }, [open, showPoints, fetchStatut]);

  // ✅ MODE TEST — accès IA gratuit pour tous (étudiants compris)
  // Pour réactiver le paiement : remplacer la ligne ci-dessous par la logique d'origine
  const hasAccess = true;
  const estAbonne = true;

  const handleClick = () => {
    setOpen(true);
  };

  const btnBg    = 'linear-gradient(135deg, #0EA5E9, #8B5CF6)';
  const dotColor = '#10B981';

  return (
    <>
      {/* ─── Bouton flottant ─── */}
      {!open && (
        <motion.button
          initial={{ scale: 0, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          whileHover={{ scale: 1.1 }}
          whileTap={{ scale: 0.93 }}
          onClick={handleClick}
          title={hasAccess ? 'Assistant IA RevisIA_H24' : 'S\'abonner pour accéder à l\'IA'}
          style={{
            position: 'fixed',
            bottom: '88px',  /* au-dessus de la bottom nav sur mobile */
            right: '18px',
            zIndex: 1990,
            width: '58px', height: '58px',
            borderRadius: '50%',
            border: 'none',
            cursor: 'pointer',
            background: btnBg,
            boxShadow: hasAccess
              ? '0 8px 28px rgba(139,92,246,0.5)'
              : '0 8px 28px rgba(249,115,22,0.5)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            color: 'white'
          }}
        >
          {hasAccess ? <Sparkles size={24} /> : <Crown size={24} />}

          {/* Pastille statut */}
          <span style={{
            position: 'absolute', top: '4px', right: '4px',
            width: '13px', height: '13px', borderRadius: '50%',
            background: dotColor, border: '2px solid white'
          }} />

          {/* Badge "GRATUIT" en mode test */}
          <motion.span
            initial={{ scale: 0 }} animate={{ scale: 1 }}
            style={{
              position: 'absolute', bottom: '-5px', left: '-5px',
              background: 'linear-gradient(135deg, #059669, #10B981)',
              borderRadius: '10px', padding: '2px 6px',
              fontSize: '0.55rem', fontWeight: '800', color: 'white',
              whiteSpace: 'nowrap',
              display: 'flex', alignItems: 'center', gap: '2px'
            }}
          >
            <Zap size={9} color="white" />
            IA libre
          </motion.span>
        </motion.button>
      )}

      {/* ─── Overlay AILab ─── */}
      <AnimatePresence>
        {open && (
          <motion.div
            className="floating-ai-overlay"
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            onClick={() => setOpen(false)}
            style={{
              position: 'fixed', inset: 0, zIndex: 9999,
              background: 'rgba(2,6,23,0.82)',
              backdropFilter: 'blur(6px)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              padding: '2vh 2vw'
            }}
          >
            <motion.div
              className="floating-ai-panel"
              initial={{ scale: 0.9, y: 30, opacity: 0 }}
              animate={{ scale: 1,   y: 0,  opacity: 1 }}
              exit={{ scale: 0.9, y: 30, opacity: 0 }}
              transition={{ type: 'spring', damping: 24, stiffness: 280 }}
              onClick={e => e.stopPropagation()}
              style={{
                position: 'relative',
                width: '100%', maxWidth: '900px',
                height: 'min(92vh, 820px)',
                background: '#07101E',
                borderRadius: '20px',
                border: '1px solid rgba(56,189,248,0.2)',
                boxShadow: '0 24px 64px rgba(0,0,0,0.5)',
                overflow: 'hidden',
                display: 'flex', flexDirection: 'column'
              }}
            >
              {/* Header overlay */}
              <div style={{
                display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                padding: '13px 18px',
                borderBottom: '1px solid rgba(56,189,248,0.15)',
                background: '#0c1a3a',
                flexShrink: 0
              }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                  <Sparkles size={17} color="#38BDF8" />
                  <span style={{ color: '#f0f9ff', fontWeight: '800', fontSize: '0.93rem' }}>
                    RevisIA_H24 — Assistant IA
                  </span>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  {/* Badge abonnement cliquable */}
                  {isEtudiantRole && statutIA !== null && (
                    <button
                      onClick={() => { setOpen(false); setShowPoints(true); }}
                      style={{
                        display: 'flex', alignItems: 'center', gap: '5px',
                        padding: '5px 11px', borderRadius: '9px', border: 'none',
                        background: statutIA?.abonnementActif
                          ? 'rgba(168,85,247,0.15)'
                          : 'rgba(255,193,7,0.1)',
                        cursor: 'pointer',
                        color: statutIA?.abonnementActif ? '#A855F7' : '#FFD700',
                        fontSize: '0.77rem', fontWeight: '800'
                      }}
                    >
                      {statutIA?.abonnementActif ? <Crown size={12}/> : <Zap size={12}/>}
                      {statutIA?.abonnementActif ? 'PRO ✓' : `${statutIA?.pointsIA ?? 0} pts`}
                    </button>
                  )}
                  <button
                    onClick={() => setOpen(false)}
                    style={{
                      width: '36px', height: '36px', borderRadius: '50%',
                      border: 'none', cursor: 'pointer',
                      background: 'rgba(239,68,68,0.15)', color: '#EF4444',
                      display: 'flex', alignItems: 'center', justifyContent: 'center'
                    }}
                  >
                    <X size={18} />
                  </button>
                </div>
              </div>

              {/* Contenu — UnifiedAI (interface IA unique) */}
              <div style={{ flex: 1, overflow: 'hidden', display: 'flex', flexDirection: 'column' }}>
                <UnifiedAI
                  user={user}
                  persistKey={user?.id ? `float_${user.id}` : 'float_guest'}
                  style={{ borderRadius: 0, border: 'none', height: '100%' }}
                />
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ─── PointsManager ─── */}
      {showPoints && (
        <PointsManager
          open={showPoints}
          onClose={() => { setShowPoints(false); fetchStatut(); }}
          onUpdated={(s) => setStatutIA(s)}
        />
      )}
    </>
  );
};

export default FloatingAIAssistant;
