import React, { useState, useEffect, useCallback } from 'react';
import { X, Zap, Gift, Loader, Check, Copy, Crown, Info,
         Wallet, Smartphone, CreditCard, Shield, ArrowUpRight, FlaskConical } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { paiementAPI } from '../services/api';
import { pushBackHandler } from '../utils/backHandler';

/* ─────────────────────────────────────────────────────────────────────────────
   PointsManager — Wallet IA complet (mode simulation en attendant FedaPay)
   Flow :  Recharger FCFA (simulé) → Acheter pack de points → Utiliser l'IA
   Quand les vraies clés FedaPay arriveront : seul le backend /recharger change.
   ───────────────────────────────────────────────────────────────────────────── */

const PACK_OPTIONS = [
  { label: '2 000 FCFA', price: 2000, points: 40,  icon: '⚡', desc: 'Pack Essentiel', color: '#F97316', popular: true  },
  { label: '5 000 FCFA', price: 5000, points: 110, icon: '🔥', desc: 'Pack Avancé',    color: '#8B5CF6', popular: false },
  { label: '10 000 FCFA',price:10000, points: 250, icon: '🚀', desc: 'Pack Expert',    color: '#38BDF8', popular: false },
];

const ABD_PRICE = 5000; // prix abonnement mensuel PREMIUM

const PointsManager = ({ open, onClose, onUpdated, initialStatut }) => {
  const [statut, setStatut]           = useState(initialStatut || null);
  const [loading, setLoading]         = useState(false);
  const [busy, setBusy]               = useState('');
  const [toast, setToast]             = useState(null);
  const [tab, setTab]                 = useState('wallet'); // wallet | abonnement | partager
  const [rechargeMontant, setRechargeMontant] = useState('');
  const [selectedPack, setSelectedPack]       = useState(null);
  const [donPoints, setDonPoints]     = useState('');
  const [codeGenere, setCodeGenere]   = useState('');
  const [codeRecu, setCodeRecu]       = useState('');
  const [copied, setCopied]           = useState(false);

  const showToast = (msg, type = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3500);
  };

  /* ⚠️ axios brut — bypass intercepteur 401→logout */
  const fetchStatut = useCallback(async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      if (!token) return;
      const { default: axios } = await import('axios');
      const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8080/api';
      const res = await axios.get(`${apiUrl}/paiements/statut-ia`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setStatut(res.data);
      if (onUpdated) onUpdated(res.data);
    } catch { /* silencieux */ } finally { setLoading(false); }
  }, [onUpdated]);

  useEffect(() => { if (initialStatut) setStatut(initialStatut); }, [initialStatut]);
  useEffect(() => { if (open) fetchStatut(); }, [open, fetchStatut]);

  useEffect(() => {
    if (!open) return undefined;
    const off = pushBackHandler(() => {
      if (onClose) onClose();
      return true;
    });
    return off;
  }, [open, onClose]);

  const handle = async (key, fn, successMsg) => {
    setBusy(key);
    try {
      const res = await fn();
      if (res.data?.message) showToast(res.data.message);
      else if (successMsg) showToast(successMsg);
      await fetchStatut();
      return res.data;
    } catch (e) {
      showToast(e.response?.data?.error || 'Action impossible', 'error');
      return null;
    } finally { setBusy(''); }
  };

  const recharger = () => {
    const m = parseFloat(rechargeMontant);
    if (!m || m <= 0) { showToast('Entrez un montant valide', 'error'); return; }
    handle('recharge', () => paiementAPI.recharger(m), 'Recharge effectuée !').then(() => setRechargeMontant(''));
  };

  const souscrire = () => {
    handle('abo', () => paiementAPI.souscrireAbonnement(),
      `Abonnement PREMIUM activé ! 🎉`);
  };

  const acheterPack = () => {
    if (!selectedPack) { showToast('Choisissez un pack', 'error'); return; }
    if (solde < selectedPack.price) {
      showToast(`Solde insuffisant — rechargez d'abord`, 'error');
      document.getElementById('pm-recharge-section')?.scrollIntoView({ behavior: 'smooth' });
      setRechargeMontant(String(selectedPack.price - solde));
      return;
    }
    handle('pack', () => paiementAPI.acheterPoints(selectedPack.price),
      `+${selectedPack.points} points IA crédités !`).then(() => setSelectedPack(null));
  };

  const genererDon = async () => {
    const n = parseInt(donPoints, 10);
    if (!n || n <= 0) { showToast('Entrez un nombre de points', 'error'); return; }
    if (n > points) { showToast('Pas assez de points', 'error'); return; }
    const data = await handle('don', () => paiementAPI.genererCodeDon(n));
    if (data?.code) { setCodeGenere(data.code); setDonPoints(''); }
  };

  const utiliserCode = async () => {
    if (!codeRecu.trim()) { showToast('Entrez un code', 'error'); return; }
    const data = await handle('recu', () => paiementAPI.utiliserCodeDon(codeRecu.trim()));
    if (data) setCodeRecu('');
  };

  const copierCode = () => {
    navigator.clipboard.writeText(codeGenere);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  /* Valeurs dérivées */
  const abonne       = statut?.abonnementActif || statut?.abonne;
  const devise       = statut?.devise || 'FCFA';
  const points       = statut?.pointsIA ?? 0;
  const solde        = statut?.solde ?? 0;
  const pointsCout   = statut?.pointsParDocument ?? 2;
  const prixAbo      = statut?.prixAbonnement ?? ABD_PRICE;
  const jourRestants = (() => {
    if (!statut?.dateFinAbonnement) return null;
    const diff = new Date(statut.dateFinAbonnement) - new Date();
    return Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));
  })();

  const TABS = [
    { id: 'wallet',    label: 'Portefeuille', icon: <Wallet size={14} /> },
    { id: 'abonnement',label: abonne ? 'IA Active' : 'Abonnement', icon: <Zap size={14} /> },
    { id: 'partager',  label: 'Partager',     icon: <Gift size={14} /> },
  ];

  return (
    <AnimatePresence>
      {open && (
        <motion.div
          initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
          onClick={onClose}
          style={{
            position: 'fixed', inset: 0, zIndex: 10000,
            background: 'rgba(2,6,23,0.87)', backdropFilter: 'blur(12px)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            padding: '16px',
          }}
        >
          <motion.div
            initial={{ scale: 0.88, y: 32, opacity: 0 }}
            animate={{ scale: 1, y: 0, opacity: 1 }}
            exit={{ scale: 0.88, y: 16, opacity: 0 }}
            transition={{ type: 'spring', damping: 22, stiffness: 300 }}
            onClick={e => e.stopPropagation()}
            style={{
              width: '100%', maxWidth: '460px',
              maxHeight: '92vh', overflowY: 'auto',
              background: 'white',
              borderRadius: '28px',
              border: '1px solid rgba(56,189,248,0.2)',
              boxShadow: '0 40px 100px rgba(0,0,0,0.7), 0 0 80px rgba(56,189,248,0.08)',
              overflow: 'hidden', position: 'relative',
            }}
          >
            {/* Fond déco */}
            <div style={{ position: 'absolute', top: -80, right: -80, width: 260, height: 260,
              background: 'radial-gradient(circle, rgba(56,189,248,0.1) 0%, transparent 70%)',
              borderRadius: '50%', pointerEvents: 'none' }} />

            {/* ── HEADER ── */}
            <div style={{
              padding: '20px 20px 0',
              background: 'linear-gradient(180deg, rgba(56,189,248,0.07) 0%, transparent 100%)',
              borderBottom: '1px solid #e2e8f0', paddingBottom: 16,
            }}>
              {/* Titre + close */}
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                  <div style={{
                    width: 42, height: 42, borderRadius: 13,
                    background: 'linear-gradient(135deg, #38BDF8, #F97316)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    boxShadow: '0 6px 20px rgba(56,189,248,0.35)',
                  }}>
                    <Zap size={20} color="#fff" />
                  </div>
                  <div>
                    <h2 style={{ margin: 0, color: '#0f172a', fontSize: '1.05rem', fontWeight: 900 }}>Mon Wallet IA</h2>
                    <p style={{ margin: 0, color: '#475569', fontSize: '0.7rem' }}>RevisIA_H24 — Portefeuille</p>
                  </div>
                </div>
                <button onClick={onClose} style={{
                  background: 'rgba(239,68,68,0.12)', color: '#EF4444',
                  border: '1px solid rgba(239,68,68,0.2)', borderRadius: '50%',
                  width: 34, height: 34, cursor: 'pointer',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                }}>
                  <X size={15} />
                </button>
              </div>

              {/* ── Bannière Mode Test ── */}
              <div style={{
                display: 'flex', alignItems: 'center', gap: 8, marginBottom: 14,
                padding: '9px 13px', borderRadius: 11,
                background: 'rgba(251,191,36,0.08)', border: '1px solid rgba(251,191,36,0.25)',
              }}>
                <FlaskConical size={13} color="#FBB724" style={{ flexShrink: 0 }} />
                <span style={{ color: '#FBB724', fontSize: '0.7rem', fontWeight: 700 }}>
                  MODE TEST — Les paiements sont simulés. L'intégration FedaPay (T-Money / Flooz / Carte) sera activée dès réception des clés API.
                </span>
              </div>

              {/* ── Soldes hero ── */}
              {loading && !statut ? (
                <div style={{ display: 'flex', gap: 10, marginBottom: 14 }}>
                  {[1,2].map(i => <div key={i} style={{ flex: 1, height: 76, borderRadius: 16, background: '#f8fafc' }} />)}
                </div>
              ) : (
                <div style={{ display: 'flex', gap: 10, marginBottom: 14 }}>
                  {/* Points IA */}
                  <motion.div key={points} initial={{ scale: 0.95 }} animate={{ scale: 1 }}
                    style={{
                      flex: 1, padding: '14px 16px', borderRadius: 16, position: 'relative', overflow: 'hidden',
                      background: 'linear-gradient(135deg, rgba(56,189,248,0.14), rgba(56,189,248,0.05))',
                      border: '1px solid rgba(56,189,248,0.3)',
                    }}
                  >
                    <div style={{ position: 'absolute', top: 6, right: 8, opacity: 0.1 }}><Zap size={34} color="#38BDF8" /></div>
                    <div style={{ fontSize: '1.8rem', fontWeight: 900, color: '#38BDF8', lineHeight: 1 }}>{points}</div>
                    <div style={{ fontSize: '0.68rem', color: '#475569', fontWeight: 700, textTransform: 'uppercase', marginTop: 3 }}>Points IA</div>
                    {abonne ? (
                      <div style={{ marginTop: 5 }}>
                        <div style={{ display: 'inline-flex', alignItems: 'center', gap: 3,
                          background: 'rgba(16,185,129,0.2)', borderRadius: 6, padding: '2px 7px',
                          fontSize: '0.62rem', color: '#10B981', fontWeight: 800 }}>
                          <Check size={9} /> PREMIUM
                        </div>
                        {jourRestants !== null && (
                          <div style={{ fontSize: '0.6rem', color: jourRestants <= 5 ? '#F97316' : '#64748B', marginTop: 2 }}>
                            {jourRestants <= 0 ? '⚠️ Expiré' : `⏳ ${jourRestants}j restants`}
                          </div>
                        )}
                      </div>
                    ) : (
                      <div style={{ marginTop: 4, fontSize: '0.6rem', color: '#475569' }}>
                        {pointsCout} pt/utilisation IA
                      </div>
                    )}
                  </motion.div>

                  {/* Solde FCFA */}
                  <motion.div key={solde} initial={{ scale: 0.95 }} animate={{ scale: 1 }}
                    style={{
                      flex: 1, padding: '14px 16px', borderRadius: 16, position: 'relative', overflow: 'hidden',
                      background: 'linear-gradient(135deg, rgba(16,185,129,0.14), rgba(16,185,129,0.05))',
                      border: '1px solid rgba(16,185,129,0.3)',
                    }}
                  >
                    <div style={{ position: 'absolute', top: 6, right: 8, opacity: 0.1 }}><Wallet size={34} color="#10B981" /></div>
                    <div style={{ fontSize: '1.45rem', fontWeight: 900, color: '#10B981', lineHeight: 1 }}>
                      {solde.toLocaleString('fr-FR')}
                    </div>
                    <div style={{ fontSize: '0.68rem', color: '#475569', fontWeight: 700, textTransform: 'uppercase', marginTop: 3 }}>{devise}</div>
                    <div style={{ marginTop: 4, fontSize: '0.6rem', color: '#475569' }}>Solde portefeuille</div>
                  </motion.div>
                </div>
              )}

              {/* ── Tabs ── */}
              <div style={{ display: 'flex', gap: 5, background: '#f8fafc', borderRadius: 12, padding: 3 }}>
                {TABS.map(t => (
                  <button key={t.id} onClick={() => setTab(t.id)} style={{
                    flex: 1, padding: '8px 4px', borderRadius: 10, border: 'none', cursor: 'pointer',
                    background: tab === t.id ? 'linear-gradient(135deg,#38BDF8,#F97316)' : 'transparent',
                    color: tab === t.id ? '#fff' : '#64748B',
                    fontWeight: 700, fontSize: '0.72rem',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 4,
                    transition: 'all 0.22s',
                    boxShadow: tab === t.id ? '0 3px 10px rgba(56,189,248,0.3)' : 'none',
                  }}>
                    {t.icon} {t.label}
                  </button>
                ))}
              </div>
            </div>

            {/* ── CONTENU ONGLETS ── */}
            <div style={{ padding: '16px 20px 22px' }}>
              <AnimatePresence mode="wait">

                {/* ══ ONGLET PORTEFEUILLE ══ */}
                {tab === 'wallet' && (
                  <motion.div key="wallet"
                    initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -10 }}
                  >
                    {/* Indicateur 2 étapes */}
                    <div style={{
                      display: 'flex', alignItems: 'center', gap: 6, marginBottom: 14,
                      padding: '9px 13px', borderRadius: 11,
                      background: 'rgba(56,189,248,0.06)', border: '1px solid rgba(56,189,248,0.14)',
                    }}>
                      {[
                        { n: '1', label: 'Recharger FCFA', color: '#38BDF8' },
                        { n: '→', label: null, color: '#475569' },
                        { n: '2', label: 'Acheter des points', color: '#F97316' },
                      ].map((s, i) => s.label ? (
                        <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 6, flex: 1 }}>
                          <div style={{ width: 20, height: 20, borderRadius: '50%', background: `${s.color}25`,
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                            fontSize: '0.62rem', fontWeight: 900, color: s.color, flexShrink: 0 }}>{s.n}</div>
                          <span style={{ fontSize: '0.72rem', color: '#475569' }}>{s.label}</span>
                        </div>
                      ) : (
                        <span key={i} style={{ color: '#475569', fontSize: '0.7rem' }}>→</span>
                      ))}
                    </div>

                    {/* Alerte solde insuffisant */}
                    {selectedPack && solde < selectedPack.price && (
                      <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }}
                        style={{ padding: '9px 13px', borderRadius: 11, marginBottom: 12,
                          background: 'rgba(239,68,68,0.09)', border: '1px solid rgba(239,68,68,0.28)',
                          display: 'flex', alignItems: 'center', gap: 8 }}>
                        <Info size={13} color="#EF4444" />
                        <div>
                          <div style={{ color: '#EF4444', fontWeight: 700, fontSize: '0.76rem' }}>Solde insuffisant</div>
                          <div style={{ color: '#475569', fontSize: '0.68rem' }}>
                            Rechargez {(selectedPack.price - solde).toLocaleString('fr-FR')} {devise} supplémentaires ci-dessous.
                          </div>
                        </div>
                      </motion.div>
                    )}

                    {/* Packs */}
                    <p style={{ color: '#475569', fontSize: '0.72rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.5px', margin: '0 0 10px' }}>
                      ⚡ Packs de points IA
                    </p>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 14 }}>
                      {PACK_OPTIONS.map((pack, i) => (
                        <motion.button key={i}
                          whileHover={{ scale: 1.015 }} whileTap={{ scale: 0.98 }}
                          onClick={() => setSelectedPack(selectedPack?.label === pack.label ? null : pack)}
                          style={{
                            display: 'flex', alignItems: 'center', gap: 12,
                            padding: '12px 14px', borderRadius: 14, cursor: 'pointer',
                            background: selectedPack?.label === pack.label
                              ? `linear-gradient(135deg, ${pack.color}22, ${pack.color}0d)`
                              : '#f8fafc',
                            border: selectedPack?.label === pack.label
                              ? `2px solid ${pack.color}` : '1px solid #e2e8f0',
                            transition: 'all 0.22s', position: 'relative',
                          }}
                        >
                          <div style={{ width: 40, height: 40, borderRadius: 11, fontSize: 20,
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                            background: `${pack.color}18`, border: `1px solid ${pack.color}35` }}>
                            {pack.icon}
                          </div>
                          <div style={{ flex: 1, textAlign: 'left' }}>
                            <div style={{ fontWeight: 800, color: '#1E293B', fontSize: '0.88rem' }}>{pack.desc}</div>
                            <div style={{ fontSize: '0.74rem', color: '#475569' }}>
                              <span style={{ color: pack.color, fontWeight: 700 }}>+{pack.points} pts</span>
                              <span style={{ margin: '0 5px', opacity: 0.4 }}>·</span>
                              <span>{pack.label}</span>
                              {solde >= pack.price && (
                                <span style={{ marginLeft: 6, color: '#10B981', fontSize: '0.65rem', fontWeight: 700 }}>✓ Solde OK</span>
                              )}
                            </div>
                          </div>
                          {pack.popular && (
                            <div style={{ background: 'linear-gradient(135deg,#F97316,#FB923C)', color: '#fff',
                              fontSize: '0.58rem', fontWeight: 800, padding: '2px 7px', borderRadius: 5 }}>
                              POPULAIRE
                            </div>
                          )}
                          {selectedPack?.label === pack.label && <Check size={16} color={pack.color} />}
                        </motion.button>
                      ))}
                    </div>

                    {/* Bouton acheter pack */}
                    {selectedPack && (
                      <motion.button
                        initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }}
                        whileTap={{ scale: 0.97 }}
                        onClick={acheterPack}
                        disabled={busy === 'pack'}
                        style={{
                          width: '100%', padding: '13px', borderRadius: 12, border: `2px solid ${solde < selectedPack.price ? 'rgba(249,115,22,0.4)' : 'transparent'}`,
                          cursor: 'pointer', marginBottom: 14,
                          background: solde < selectedPack.price
                            ? 'rgba(249,115,22,0.12)'
                            : 'linear-gradient(135deg, #38BDF8, #F97316)',
                          color: '#0f172a', fontWeight: 800, fontSize: '0.92rem',
                          display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
                          boxShadow: solde >= selectedPack.price ? '0 6px 20px rgba(56,189,248,0.35)' : 'none',
                        }}
                      >
                        {busy === 'pack'
                          ? <Loader size={18} className="anim-spin" />
                          : solde < selectedPack.price
                            ? <><ArrowUpRight size={16} /> Recharger {(selectedPack.price - solde).toLocaleString('fr-FR')} {devise} d'abord ↓</>
                            : <><ArrowUpRight size={16} /> Acheter — +{selectedPack.points} pts IA</>
                        }
                      </motion.button>
                    )}

                    {/* Recharge portefeuille */}
                    <div id="pm-recharge-section" style={{
                      background: '#f8fafc', borderRadius: 14,
                      border: '1px solid #e2e8f0', padding: '14px',
                    }}>
                      <p style={{ color: '#fff', fontWeight: 700, margin: '0 0 10px',
                        display: 'flex', alignItems: 'center', gap: 6, fontSize: '0.85rem' }}>
                        <Wallet size={14} color="#10B981" /> Recharger mon portefeuille
                      </p>
                      <div style={{ display: 'flex', gap: 8, marginBottom: 10 }}>
                        <input
                          type="number"
                          placeholder={`Montant en ${devise}`}
                          value={rechargeMontant}
                          onChange={e => setRechargeMontant(e.target.value)}
                          style={{
                            flex: 1, padding: '10px 13px', borderRadius: 10,
                            border: '1px solid rgba(255,255,255,0.11)',
                            background: '#f8fafc', color: '#0f172a',
                            fontSize: '0.92rem', outline: 'none',
                          }}
                        />
                        <motion.button
                          whileTap={{ scale: 0.97 }}
                          onClick={recharger}
                          disabled={busy === 'recharge'}
                          style={{
                            padding: '10px 16px', borderRadius: 10, border: 'none',
                            cursor: 'pointer',
                            background: rechargeMontant ? 'linear-gradient(135deg,#10B981,#0D9488)' : '#f1f5f9',
                            color: rechargeMontant ? '#fff' : '#475569',
                            fontWeight: 700, display: 'flex', alignItems: 'center', gap: 5,
                          }}
                        >
                          {busy === 'recharge' ? <Loader size={15} className="anim-spin" /> : 'Recharger'}
                        </motion.button>
                      </div>
                      {/* Montants rapides */}
                      <div style={{ display: 'flex', gap: 6, marginBottom: 10 }}>
                        {[1000, 2000, 5000, 10000].map(m => (
                          <button key={m} onClick={() => setRechargeMontant(String(m))}
                            style={{
                              flex: 1, padding: '5px 0', borderRadius: 8, border: 'none', cursor: 'pointer',
                              background: rechargeMontant === String(m) ? 'rgba(16,185,129,0.2)' : '#f1f5f9',
                              color: rechargeMontant === String(m) ? '#10B981' : '#64748B',
                              fontWeight: 700, fontSize: '0.65rem',
                            }}>
                            {m >= 1000 ? `${m/1000}k` : m}
                          </button>
                        ))}
                      </div>
                      {/* Méthodes de paiement (à venir) */}
                      <div style={{ display: 'flex', gap: 8 }}>
                        {[
                          { icon: <Smartphone size={13} />, label: 'T-Money / Flooz', color: '#F97316' },
                          { icon: <CreditCard size={13} />, label: 'Carte bancaire',  color: '#38BDF8' },
                          { icon: <Shield size={13} />,     label: 'FedaPay sécurisé',color: '#10B981' },
                        ].map((m, i) => (
                          <div key={i} style={{
                            flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3,
                            padding: '7px 4px', borderRadius: 9,
                            background: '#f8fafc', border: '1px solid #e2e8f0',
                            color: m.color, fontSize: '0.62rem', fontWeight: 600,
                          }}>
                            {m.icon}
                            <span style={{ color: '#475569', textAlign: 'center', lineHeight: 1.2 }}>{m.label}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  </motion.div>
                )}

                {/* ══ ONGLET ABONNEMENT ══ */}
                {tab === 'abonnement' && (
                  <motion.div key="abo"
                    initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -10 }}
                  >
                    {abonne ? (
                      /* ─ Déjà abonné ─ */
                      <motion.div initial={{ scale: 0.95 }} animate={{ scale: 1 }}
                        style={{
                          textAlign: 'center', padding: '28px 18px',
                          background: 'linear-gradient(135deg, rgba(16,185,129,0.11), rgba(56,189,248,0.07))',
                          borderRadius: 18, border: '1px solid rgba(16,185,129,0.28)',
                        }}
                      >
                        <div style={{
                          width: 64, height: 64, borderRadius: '50%',
                          background: 'linear-gradient(135deg,#10B981,#38BDF8)',
                          display: 'flex', alignItems: 'center', justifyContent: 'center',
                          margin: '0 auto 14px', boxShadow: '0 10px 28px rgba(16,185,129,0.35)',
                        }}>
                          <Crown size={30} color="#fff" />
                        </div>
                        <h3 style={{ color: '#10B981', fontWeight: 900, fontSize: '1.1rem', margin: '0 0 6px' }}>
                          IA Active ✓
                        </h3>
                        <p style={{ color: '#475569', fontSize: '0.8rem', margin: '0 0 14px' }}>
                          Vous avez accès illimité à toutes les fonctionnalités IA.
                        </p>
                        {jourRestants !== null && (
                          <div style={{
                            display: 'inline-flex', alignItems: 'center', gap: 6,
                            padding: '7px 14px', borderRadius: 10,
                            background: jourRestants <= 5 ? 'rgba(249,115,22,0.12)' : '#f1f5f9',
                            border: `1px solid ${jourRestants <= 5 ? 'rgba(249,115,22,0.3)' : 'rgba(255,255,255,0.1)'}`,
                            color: jourRestants <= 5 ? '#F97316' : '#94A3B8',
                            fontSize: '0.78rem', fontWeight: 700,
                          }}>
                            {jourRestants <= 0
                              ? '⚠️ Expiré — renouvelez ci-dessous'
                              : `⏳ Expire dans ${jourRestants} jour${jourRestants !== 1 ? 's' : ''}`}
                          </div>
                        )}
                        <p style={{ color: '#475569', fontSize: '0.72rem', margin: '14px 0 0' }}>
                          Renouveler pour +30 jours : {prixAbo.toLocaleString('fr-FR')} {devise}
                          {solde >= prixAbo
                            ? <span style={{ color: '#10B981', marginLeft: 6, fontWeight: 700 }}>✓ Solde OK</span>
                            : <span style={{ color: '#EF4444', marginLeft: 6 }}>solde insuffisant</span>}
                        </p>
                        <motion.button whileTap={{ scale: 0.97 }} onClick={souscrire}
                          disabled={busy === 'abo' || solde < prixAbo}
                          style={{
                            marginTop: 12, padding: '11px 24px', borderRadius: 12, border: 'none',
                            cursor: solde >= prixAbo ? 'pointer' : 'not-allowed',
                            background: solde >= prixAbo ? 'linear-gradient(135deg,#10B981,#0D9488)' : '#f1f5f9',
                            color: solde >= prixAbo ? '#fff' : '#475569', fontWeight: 800,
                          }}>
                          {busy === 'abo' ? <Loader size={16} className="anim-spin" /> : 'Renouveler l\'abonnement'}
                        </motion.button>
                      </motion.div>
                    ) : (
                      /* ─ Pas encore abonné ─ */
                      <div>
                        {/* Card PREMIUM */}
                        <div style={{
                          padding: '20px', borderRadius: 18, marginBottom: 14,
                          background: 'linear-gradient(135deg, rgba(168,85,247,0.15), rgba(139,92,246,0.08))',
                          border: '1px solid rgba(168,85,247,0.3)',
                        }}>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 14 }}>
                            <div style={{
                              width: 44, height: 44, borderRadius: 12,
                              background: 'linear-gradient(135deg,#A855F7,#6D28D9)',
                              display: 'flex', alignItems: 'center', justifyContent: 'center',
                              boxShadow: '0 6px 18px rgba(168,85,247,0.4)',
                            }}>
                              <Crown size={22} color="#fff" />
                            </div>
                            <div>
                              <div style={{ color: '#A855F7', fontWeight: 900, fontSize: '1rem' }}>PREMIUM IA</div>
                              <div style={{ color: '#475569', fontSize: '0.7rem' }}>Accès illimité · 30 jours</div>
                            </div>
                            <div style={{ marginLeft: 'auto', textAlign: 'right' }}>
                              <div style={{ color: '#4c1d95', fontWeight: 900, fontSize: '1.1rem' }}>
                                {prixAbo.toLocaleString('fr-FR')} {devise}
                              </div>
                              <div style={{ color: '#475569', fontSize: '0.65rem' }}>/mois</div>
                            </div>
                          </div>
                          {[
                            '✓ IA illimitée (résumé, quiz, correction, chat)',
                            '✓ Accès prioritaire aux nouvelles fonctionnalités',
                            '✓ Points IA bonus inclus à chaque renouvellement',
                          ].map((item, i) => (
                            <div key={i} style={{ color: '#475569', fontSize: '0.74rem', marginBottom: 5, display: 'flex', alignItems: 'center', gap: 7 }}>
                              <div style={{ width: 5, height: 5, borderRadius: '50%', background: '#A855F7', flexShrink: 0 }} />
                              {item}
                            </div>
                          ))}
                        </div>

                        {/* Solde dispo vs prix */}
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                          padding: '10px 14px', borderRadius: 11, marginBottom: 12,
                          background: solde >= prixAbo ? 'rgba(16,185,129,0.07)' : 'rgba(249,115,22,0.07)',
                          border: `1px solid ${solde >= prixAbo ? 'rgba(16,185,129,0.25)' : 'rgba(249,115,22,0.25)'}`,
                        }}>
                          <div>
                            <div style={{ color: '#475569', fontSize: '0.68rem' }}>Votre solde</div>
                            <div style={{ color: '#0c1730', fontWeight: 800 }}>{solde.toLocaleString('fr-FR')} {devise}</div>
                          </div>
                          {solde >= prixAbo
                            ? <div style={{ color: '#10B981', fontWeight: 800, fontSize: '0.78rem' }}>✓ Solde suffisant</div>
                            : <div style={{ color: '#F97316', fontSize: '0.72rem', textAlign: 'right' }}>
                                Manque {(prixAbo - solde).toLocaleString('fr-FR')} {devise}
                                <br /><span style={{ fontSize: '0.62rem', color: '#475569' }}>→ rechargez dans l'onglet Portefeuille</span>
                              </div>
                          }
                        </div>

                        <motion.button whileTap={{ scale: 0.97 }} onClick={souscrire}
                          disabled={busy === 'abo' || solde < prixAbo}
                          style={{
                            width: '100%', padding: '13px', borderRadius: 12, border: 'none',
                            cursor: solde >= prixAbo ? 'pointer' : 'not-allowed',
                            background: solde >= prixAbo
                              ? 'linear-gradient(135deg,#A855F7,#6D28D9)'
                              : '#f1f5f9',
                            color: solde >= prixAbo ? '#fff' : '#475569',
                            fontWeight: 800, fontSize: '0.92rem',
                            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
                            boxShadow: solde >= prixAbo ? '0 6px 20px rgba(168,85,247,0.35)' : 'none',
                          }}>
                          {busy === 'abo'
                            ? <Loader size={18} className="anim-spin" />
                            : solde >= prixAbo
                              ? <><Crown size={16} /> S'abonner PREMIUM — {prixAbo.toLocaleString('fr-FR')} {devise}</>
                              : <><Wallet size={16} /> Rechargez d'abord votre portefeuille</>
                          }
                        </motion.button>
                      </div>
                    )}
                  </motion.div>
                )}

                {/* ══ ONGLET PARTAGER ══ */}
                {tab === 'partager' && (
                  <motion.div key="partager"
                    initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -10 }}
                  >
                    {/* Utiliser un code reçu */}
                    <div style={{
                      background: '#f8fafc', borderRadius: 14,
                      border: '1px solid #e2e8f0', padding: '14px', marginBottom: 12,
                    }}>
                      <p style={{ color: '#fff', fontWeight: 700, margin: '0 0 10px',
                        fontSize: '0.85rem', display: 'flex', alignItems: 'center', gap: 6 }}>
                        <Gift size={14} color="#10B981" /> Utiliser un code reçu
                      </p>
                      <div style={{ display: 'flex', gap: 8 }}>
                        <input
                          type="text"
                          placeholder="PTS-XXXXXX"
                          value={codeRecu}
                          onChange={e => setCodeRecu(e.target.value.toUpperCase())}
                          style={{
                            flex: 1, padding: '10px 13px', borderRadius: 10,
                            border: '1px solid rgba(255,255,255,0.11)',
                            background: '#f8fafc', color: '#0f172a',
                            fontSize: '0.92rem', outline: 'none', letterSpacing: '1px', fontWeight: 700,
                          }}
                        />
                        <motion.button whileTap={{ scale: 0.97 }} onClick={utiliserCode}
                          disabled={busy === 'recu' || !codeRecu.trim()}
                          style={{
                            padding: '10px 15px', borderRadius: 10, border: 'none', cursor: 'pointer',
                            background: codeRecu.trim() ? 'linear-gradient(135deg,#10B981,#0D9488)' : '#f1f5f9',
                            color: codeRecu.trim() ? '#fff' : '#475569', fontWeight: 700,
                            display: 'flex', alignItems: 'center', gap: 5,
                          }}>
                          {busy === 'recu' ? <Loader size={15} className="anim-spin" /> : <><Check size={14} /> OK</>}
                        </motion.button>
                      </div>
                    </div>

                    {/* Générer un code */}
                    <div style={{
                      background: '#f8fafc', borderRadius: 14,
                      border: '1px solid #e2e8f0', padding: '14px',
                    }}>
                      <p style={{ color: '#fff', fontWeight: 700, margin: '0 0 4px',
                        fontSize: '0.85rem', display: 'flex', alignItems: 'center', gap: 6 }}>
                        <Gift size={14} color="#F97316" /> Offrir des points
                      </p>
                      <p style={{ color: '#475569', fontSize: '0.68rem', margin: '0 0 10px' }}>
                        Points débités immédiatement de votre solde.
                      </p>
                      <div style={{ display: 'flex', gap: 8 }}>
                        <input
                          type="number"
                          placeholder={`Points à offrir (dispo : ${points})`}
                          min="1" max={points}
                          value={donPoints}
                          onChange={e => setDonPoints(e.target.value)}
                          style={{
                            flex: 1, padding: '10px 13px', borderRadius: 10,
                            border: '1px solid rgba(255,255,255,0.11)',
                            background: '#f8fafc', color: '#0f172a',
                            fontSize: '0.92rem', outline: 'none',
                          }}
                        />
                        <motion.button whileTap={{ scale: 0.97 }} onClick={genererDon}
                          disabled={busy === 'don' || points <= 0 || !donPoints}
                          style={{
                            padding: '10px 14px', borderRadius: 10, border: 'none',
                            cursor: points > 0 ? 'pointer' : 'not-allowed',
                            background: points > 0 && donPoints ? 'linear-gradient(135deg,#F97316,#FB923C)' : '#f1f5f9',
                            color: points > 0 && donPoints ? '#fff' : '#475569', fontWeight: 700,
                          }}>
                          {busy === 'don' ? <Loader size={15} className="anim-spin" /> : 'Générer'}
                        </motion.button>
                      </div>
                    </div>

                    {/* Code généré */}
                    {codeGenere && (
                      <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }}
                        style={{ marginTop: 12, padding: '14px', borderRadius: 13,
                          background: 'rgba(16,185,129,0.09)', border: '1px solid rgba(16,185,129,0.28)' }}>
                        <p style={{ margin: '0 0 10px', color: '#10B981', fontWeight: 700, fontSize: '0.78rem' }}>
                          ✓ Code généré — partagez-le
                        </p>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                          <div style={{
                            flex: 1, padding: '11px 14px', borderRadius: 9,
                            background: '#f0fdf4', border: '1px solid rgba(16,185,129,0.3)',
                            color: '#10B981', fontWeight: 900, fontSize: '1.1rem',
                            letterSpacing: '3px', textAlign: 'center',
                          }}>
                            {codeGenere}
                          </div>
                          <motion.button whileTap={{ scale: 0.9 }} onClick={copierCode}
                            style={{ padding: '11px 13px', borderRadius: 9, border: 'none', cursor: 'pointer',
                              background: copied ? 'rgba(16,185,129,0.28)' : '#f1f5f9',
                              color: copied ? '#10B981' : '#94A3B8' }}>
                            {copied ? <Check size={17} /> : <Copy size={17} />}
                          </motion.button>
                        </div>
                        <p style={{ margin: '7px 0 0', color: '#475569', fontSize: '0.64rem' }}>
                          Code à usage unique
                        </p>
                      </motion.div>
                    )}
                  </motion.div>
                )}

              </AnimatePresence>
            </div>

            {/* ── Toast ── */}
            <AnimatePresence>
              {toast && (
                <motion.div
                  initial={{ opacity: 0, y: 18 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 18 }}
                  style={{
                    position: 'fixed', bottom: 22, left: '50%', transform: 'translateX(-50%)',
                    zIndex: 99999, padding: '11px 20px', borderRadius: 13,
                    background: toast.type === 'error' ? 'rgba(239,68,68,0.96)' : 'rgba(16,185,129,0.96)',
                    color: '#fff', fontWeight: 700, fontSize: '0.82rem',
                    boxShadow: '0 8px 24px rgba(0,0,0,0.4)', whiteSpace: 'nowrap',
                  }}
                >
                  {toast.msg}
                </motion.div>
              )}
            </AnimatePresence>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default PointsManager;
